styles:
.reader-quote {
  font-style: normal;
  color: #ffd700;
  text-shadow: 0 0 6px rgba(255, 215, 0, 0.4);
  font-weight: 500;
}
.reader-ellipsis {
  letter-spacing: 8px;
  color: #daa520;
  text-shadow: 0 0 4px rgba(218, 165, 32, 0.3);
}
.reader-dash {
  letter-spacing: 4px;
  color: #dc143c;
  text-shadow: 0 0 6px rgba(220, 20, 60, 0.4);
}
.reader-speak {
  color: #ffd700;
  font-weight: 900;
  text-shadow: 0 0 8px rgba(255, 215, 0, 0.3);
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3.6em;
  line-height: 0.7;
  padding-right: 10px;
  padding-top: 6px;
  color: #ffd700;
  font-weight: 900;
  text-shadow: 0 0 10px rgba(255, 215, 0, 0.5), 0 0 20px rgba(255, 215, 0, 0.2);
  font-family: 'STKaiti', 'KaiTi', serif;
}
